
CREATE TABLE DEPARTMENT (Department_ID NUMBER PRIMARY KEY, Department_Name VARCHAR2(100) NOT NULL UNIQUE, Office_Location VARCHAR2(100));

CREATE TABLE PROGRAM (Program_ID NUMBER PRIMARY KEY, Program_Name VARCHAR2(100) NOT NULL UNIQUE, Degree VARCHAR2(50) NOT NULL, Duration_Years NUMBER(2) NOT NULL CHECK (Duration_Years > 0), Department_ID NUMBER NOT NULL, CONSTRAINT FK_PROGRAM_DEPARTMENT FOREIGN KEY (Department_ID) REFERENCES DEPARTMENT(Department_ID));

CREATE TABLE STUDENT (Student_ID NUMBER PRIMARY KEY, Name VARCHAR2(100) NOT NULL, Email VARCHAR2(150) NOT NULL UNIQUE, Phone VARCHAR2(20), DOB DATE, Admission_Year NUMBER(4) NOT NULL, Program_ID NUMBER NOT NULL, CONSTRAINT FK_STUDENT_PROGRAM FOREIGN KEY (Program_ID) REFERENCES PROGRAM(Program_ID));

CREATE TABLE FACULTY (Faculty_ID NUMBER PRIMARY KEY, Name VARCHAR2(100) NOT NULL, Email VARCHAR2(150) NOT NULL UNIQUE, Phone VARCHAR2(20), Designation VARCHAR2(50) NOT NULL, Department_ID NUMBER NOT NULL, CONSTRAINT FK_FACULTY_DEPARTMENT FOREIGN KEY (Department_ID) REFERENCES DEPARTMENT(Department_ID));

CREATE TABLE COURSE (Course_ID NUMBER PRIMARY KEY, Course_Name VARCHAR2(100) NOT NULL, Credits NUMBER(2) NOT NULL CHECK (Credits > 0), Course_Type VARCHAR2(30) NOT NULL, Department_ID NUMBER NOT NULL, CONSTRAINT FK_COURSE_DEPARTMENT FOREIGN KEY (Department_ID) REFERENCES DEPARTMENT(Department_ID));

CREATE TABLE COURSE_OFFERING (Offering_ID NUMBER PRIMARY KEY, Course_ID NUMBER NOT NULL, Faculty_ID NUMBER NOT NULL, Semester NUMBER(2) NOT NULL CHECK (Semester BETWEEN 1 AND 10), Academic_Year VARCHAR2(9) NOT NULL, Section VARCHAR2(10) NOT NULL, Room_No VARCHAR2(20), Max_Seats NUMBER(4) NOT NULL CHECK (Max_Seats > 0), Classes_Held NUMBER(3) DEFAULT 0 NOT NULL CHECK (Classes_Held >= 0), CONSTRAINT FK_OFFERING_COURSE FOREIGN KEY (Course_ID) REFERENCES COURSE(Course_ID), CONSTRAINT FK_OFFERING_FACULTY FOREIGN KEY (Faculty_ID) REFERENCES FACULTY(Faculty_ID), CONSTRAINT UQ_OFFERING UNIQUE (Course_ID, Semester, Academic_Year, Section));

CREATE TABLE ENROLLMENT (Enrollment_ID NUMBER PRIMARY KEY, Student_ID NUMBER NOT NULL, Offering_ID NUMBER NOT NULL, Enrollment_Date DATE DEFAULT SYSDATE NOT NULL, Status VARCHAR2(20) DEFAULT 'ENROLLED' NOT NULL CONSTRAINT CK_ENROLLMENT_STATUS CHECK (Status IN ('ENROLLED', 'DROPPED', 'COMPLETED')), CONSTRAINT FK_ENROLLMENT_STUDENT FOREIGN KEY (Student_ID) REFERENCES STUDENT(Student_ID), CONSTRAINT FK_ENROLLMENT_OFFERING FOREIGN KEY (Offering_ID) REFERENCES COURSE_OFFERING(Offering_ID), CONSTRAINT UQ_ENROLLMENT UNIQUE (Student_ID, Offering_ID));

CREATE TABLE ATTENDANCE (Attendance_ID NUMBER PRIMARY KEY, Student_ID NUMBER NOT NULL, Offering_ID NUMBER NOT NULL, Classes_Attended NUMBER(3) DEFAULT 0 NOT NULL CHECK (Classes_Attended >= 0), CONSTRAINT FK_ATTENDANCE_STUDENT FOREIGN KEY (Student_ID) REFERENCES STUDENT(Student_ID), CONSTRAINT FK_ATTENDANCE_OFFERING FOREIGN KEY (Offering_ID) REFERENCES COURSE_OFFERING(Offering_ID), CONSTRAINT UQ_ATTENDANCE UNIQUE (Student_ID, Offering_ID));

CREATE TABLE MARKS (Mark_ID NUMBER PRIMARY KEY, Student_ID NUMBER NOT NULL, Offering_ID NUMBER NOT NULL, Continuous_Assessment_Marks NUMBER(5,2) DEFAULT 0 NOT NULL CONSTRAINT CK_MARKS_CA CHECK (Continuous_Assessment_Marks BETWEEN 0 AND 30), Midterm_Marks NUMBER(5,2) DEFAULT 0 NOT NULL CONSTRAINT CK_MARKS_MIDTERM CHECK (Midterm_Marks BETWEEN 0 AND 30), Final_Exam_Marks NUMBER(5,2) DEFAULT 0 NOT NULL CONSTRAINT CK_MARKS_FINAL CHECK (Final_Exam_Marks BETWEEN 0 AND 50), CONSTRAINT FK_MARKS_STUDENT FOREIGN KEY (Student_ID) REFERENCES STUDENT(Student_ID), CONSTRAINT FK_MARKS_OFFERING FOREIGN KEY (Offering_ID) REFERENCES COURSE_OFFERING(Offering_ID), CONSTRAINT UQ_MARKS UNIQUE (Student_ID, Offering_ID));

CREATE TABLE GRADE (Grade_Code VARCHAR2(2) PRIMARY KEY, Grade_Point NUMBER(2,1) NOT NULL CHECK (Grade_Point BETWEEN 0 AND 10), Min_Percentage NUMBER(5,2) NOT NULL CHECK (Min_Percentage BETWEEN 0 AND 100), Max_Percentage NUMBER(5,2) NOT NULL CHECK (Max_Percentage BETWEEN 0 AND 100), CONSTRAINT CK_GRADE_RANGE CHECK (Min_Percentage <= Max_Percentage));

CREATE TABLE EXAM (Exam_ID NUMBER PRIMARY KEY, Offering_ID NUMBER NOT NULL, Exam_Type VARCHAR2(30) NOT NULL, Exam_Date DATE NOT NULL, Start_Time TIMESTAMP NOT NULL, End_Time TIMESTAMP NOT NULL, Venue VARCHAR2(100) NOT NULL, Max_Marks NUMBER(5,2) NOT NULL CHECK (Max_Marks > 0), Status VARCHAR2(20) DEFAULT 'SCHEDULED' NOT NULL CONSTRAINT CK_EXAM_STATUS CHECK (Status IN ('SCHEDULED', 'COMPLETED', 'CANCELLED')), CONSTRAINT FK_EXAM_OFFERING FOREIGN KEY (Offering_ID) REFERENCES COURSE_OFFERING(Offering_ID), CONSTRAINT CK_EXAM_TIME CHECK (End_Time > Start_Time));

CREATE TABLE EXAM_REGISTRATION (Exam_Registration_ID NUMBER PRIMARY KEY, Student_ID NUMBER NOT NULL, Exam_ID NUMBER NOT NULL, Registration_Date DATE DEFAULT SYSDATE NOT NULL, Status VARCHAR2(20) DEFAULT 'REGISTERED' NOT NULL CONSTRAINT CK_EXAMREG_STATUS CHECK (Status IN ('REGISTERED', 'CANCELLED')), CONSTRAINT FK_EXAMREG_STUDENT FOREIGN KEY (Student_ID) REFERENCES STUDENT(Student_ID), CONSTRAINT FK_EXAMREG_EXAM FOREIGN KEY (Exam_ID) REFERENCES EXAM(Exam_ID), CONSTRAINT UQ_EXAMREG UNIQUE (Student_ID, Exam_ID));

CREATE TABLE EXAM_RESULT (Exam_Result_ID NUMBER PRIMARY KEY, Exam_Registration_ID NUMBER NOT NULL UNIQUE, Marks_Obtained NUMBER(5,2) CHECK (Marks_Obtained >= 0), Result_Status VARCHAR2(20) NOT NULL CONSTRAINT CK_RESULT_STATUS CHECK (Result_Status IN ('PASS', 'FAIL', 'WITHHELD')), Grade_Code VARCHAR2(2), Published_Date DATE, CONSTRAINT FK_RESULT_REG FOREIGN KEY (Exam_Registration_ID) REFERENCES EXAM_REGISTRATION(Exam_Registration_ID), CONSTRAINT FK_RESULT_GRADE FOREIGN KEY (Grade_Code) REFERENCES GRADE(Grade_Code));

CREATE TABLE RE_EXAM_APPLICATION (ReExam_Application_ID NUMBER PRIMARY KEY, Exam_Result_ID NUMBER NOT NULL, Application_Date DATE DEFAULT SYSDATE NOT NULL, Reason VARCHAR2(500) NOT NULL, Status VARCHAR2(20) DEFAULT 'PENDING' NOT NULL CONSTRAINT CK_REEXAM_STATUS CHECK (Status IN ('PENDING', 'APPROVED', 'REJECTED')), Approval_Date DATE, CONSTRAINT FK_REEXAM_RESULT FOREIGN KEY (Exam_Result_ID) REFERENCES EXAM_RESULT(Exam_Result_ID));
